72	/* Find a record-capable and a playback-capable node under /dev/audio.
73	 *
74	 * Done by capability rather than by name: the device names come from the
75	 * board's audio registration, which lives in the VM board tree, and a wrong
76	 * guess would present as ENOENT at run time for no good reason.
77	 */
78	
79	static int mic_find_devices(char *inpath, char *outpath, size_t len)
80	{
81	  struct audio_caps_s caps;
82	  struct dirent *entry;
83	  char path[MIC_PATH_MAX];
84	  DIR *dirp;
85	  int found = 0;
86	  int fd;
87	
88	  inpath[0]  = '\0';
89	  outpath[0] = '\0';
90	
91	  dirp = opendir("/dev/audio");
92	  if (dirp == NULL)
93	    {
94	      printf("mic: cannot open /dev/audio: %d\n", errno);
95	      return -errno;
96	    }
97	
98	  while ((entry = readdir(dirp)) != NULL)
99	    {
100	      snprintf(path, sizeof(path), "/dev/audio/%s", entry->d_name);
101	
102	      fd = open(path, O_RDWR | O_CLOEXEC);
103	      if (fd < 0)
104	        {
105	          continue;
106	        }
107	
108	      memset(&caps, 0, sizeof(caps));
109	      caps.ac_len     = sizeof(caps);
110	      caps.ac_type    = AUDIO_TYPE_QUERY;
111	      caps.ac_subtype = AUDIO_TYPE_QUERY;
112	
113	      if (ioctl(fd, AUDIOIOC_GETCAPS, (unsigned long)&caps) == caps.ac_len)
114	        {
115	          /* Deliberately not an else-if chain: a node that reports both
116	           * directions is a legitimate answer for both roles.
117	           */
118	
119	          if (inpath[0] == '\0' &&
120	              (caps.ac_controls.b[0] & AUDIO_TYPE_INPUT) != 0)
121	            {
122	              strlcpy(inpath, path, len);
123	              found++;
124	            }
125	
126	          if (outpath[0] == '\0' &&
127	              (caps.ac_controls.b[0] & AUDIO_TYPE_OUTPUT) != 0)
128	            {
129	              strlcpy(outpath, path, len);
130	              found++;
131	            }
132	        }
133	
134	      close(fd);
135	
136	      if (inpath[0] != '\0' && outpath[0] != '\0')
137	        {
138	          break;
139	        }
140	    }
141	
142	  closedir(dirp);
143	
144	  if (inpath[0] == '\0' || outpath[0] == '\0')
145	    {
146	      printf("mic: need both a record and a playback node "
147	             "(in='%s' out='%s')\n", inpath, outpath);
148	      return -ENODEV;
149	    }
150	
151	  printf("mic: record=%s playback=%s\n", inpath, outpath);
152	  return found;
153	}
