155	static int mic_configure(int fd, int type)
156	{
157	  struct audio_caps_desc_s desc;
158	
159	  memset(&desc, 0, sizeof(desc));
160	  desc.caps.ac_len            = sizeof(struct audio_caps_s);
161	  desc.caps.ac_type           = type;
162	  desc.caps.ac_channels       = MIC_CHANNELS;
163	  desc.caps.ac_chmap          = MIC_CHMAP;
164	  desc.caps.ac_subtype        = AUDIO_FMT_PCM;
165	  desc.caps.ac_controls.hw[0] = MIC_RATE;
166	  desc.caps.ac_controls.b[3]  = MIC_RATE >> 16;
167	  desc.caps.ac_controls.b[2]  = MIC_BPSAMP;
168	
169	  if (ioctl(fd, AUDIOIOC_CONFIGURE, (unsigned long)&desc) < 0)
170	    {
171	      printf("mic: AUDIOIOC_CONFIGURE(type %d) failed: %d\n", type, errno);
172	      return -errno;
173	    }
174	
175	  return 0;
176	}
