/* Wait for every enqueued buffer to come back before freeing any of them.
 *
 * A capture ends with all of the record buffers still enqueued -- the receive
 * loop requeues each one the moment it has copied the samples out.  STOP does
 * not return them: es8311_stop asks its worker to terminate and hands back
 * only what is still sitting in its own pendq, so anything already passed down
 * to I2S_RECEIVE stays in the esp32s3 rx.act/rx.pend queues.  Freeing them at
 * that point leaves the I2S layer holding containers that point at released
 * ap_buffer_s memory, and the NEXT capture inherits it.
 *
 * That is exactly what a second "velapaw kws mic" in the same boot did: the
 * first run captured all 16000 samples, the second delivered one buffer
 * (4092 B) and then stalled with head=5 tail=1.
 *
 * head counts enqueues the upper half accepted, tail counts completions, so
 * head == tail means nothing is in flight.  Bounded, because a wedged driver
 * must not hang the shell.
 */

static void mic_drain(struct mic_ctx_s *ctx)
{
  struct audio_status_s rst;
  struct audio_status_s pst;
  struct audio_msg_s    msg;
  struct timespec       deadline;
  unsigned int          prio;
  ssize_t               size;
  int                   i;

  if (!ctx->mq_open)
    {
      return;
    }

  memset(&rst, 0, sizeof(rst));
  memset(&pst, 0, sizeof(pst));

  for (i = 0; i < MIC_DRAIN_TRIES; i++)
    {
      if (ctx->recfd >= 0)
        {
          ioctl(ctx->recfd, AUDIOIOC_GETSTATUS, (unsigned long)&rst);
        }

      if (ctx->playfd >= 0)
        {
          ioctl(ctx->playfd, AUDIOIOC_GETSTATUS, (unsigned long)&pst);
        }

      if (rst.head == rst.tail && pst.head == pst.tail)
        {
          break;
        }

      /* Keep servicing the queue -- a completion the application never
       * collects is a buffer that never gets counted home.
       */

      clock_gettime(CLOCK_REALTIME, &deadline);
      deadline.tv_nsec += MIC_DRAIN_STEP_MS * 1000000L;
      if (deadline.tv_nsec >= 1000000000L)
        {
          deadline.tv_sec  += 1;
          deadline.tv_nsec -= 1000000000L;
        }

      size = mq_timedreceive(ctx->mq, (char *)&msg, sizeof(msg), &prio,
                             &deadline);
      (void)size;   /* a timeout just means "re-check the counters" */
    }

  printf("mic: drain rec %lu/%lu play %lu/%lu%s\n",
         (unsigned long)rst.tail, (unsigned long)rst.head,
         (unsigned long)pst.tail, (unsigned long)pst.head,
         (rst.head == rst.tail && pst.head == pst.tail) ? "" : "  STUCK");
}

static void mic_cleanup(struct mic_ctx_s *ctx)
{
  struct audio_buf_desc_s desc;
  int i;

  if (ctx->rec_started)
    {
      ioctl(ctx->recfd, AUDIOIOC_STOP, 0);
    }

  if (ctx->play_started)
    {
      ioctl(ctx->playfd, AUDIOIOC_STOP, 0);
    }

  /* Must happen after STOP and before FREEBUFFER. */

  mic_drain(ctx);

