/* Wait for every enqueued buffer to come back before freeing any of them.
 *
 * A capture ends with all four record buffers still enqueued -- the receive
 * loop requeues each one the moment it has copied it out.  AUDIOIOC_STOP does
 * NOT bring those home: es8311_stop asks its worker to terminate, and the
 * worker only hands back buffers still sitting in es8311's own pendq.
 * Anything already passed down to I2S_RECEIVE stays in the esp32s3 driver's
 * rx.act / rx.pend queues, because es8311 issues no I2S_IOCTL at all (see
 * board/patches/README.md patch #11) and so never tells the I2S layer to stop.
 *
 * Freeing them at that point leaves the I2S layer holding buffer containers
 * that point at released ap_buffer_s memory, and the NEXT capture inherits it:
 * i2s_rxdma_start() bails out early while rx.act is non-empty, so RX is never
 * re-armed.  That is exactly what a second "velapaw kws mic" in the same boot
 * showed -- one buffer delivered (4092 B), then nothing.
 *
 * tail counts completions and head counts accepted enqueues, so tail == head
 * on both devices means nothing is in flight.  Bounded, because a wedged
 * driver must not hang the shell.
 */

#define MIC_DRAIN_TRIES  20      /* x 50 ms = 1 s worst case */

static void mic_drain(struct mic_ctx_s *ctx)
{
  struct audio_status_s rst;
  struct audio_status_s pst;
  struct audio_msg_s msg;
  struct timespec deadline;
  unsigned int prio;
  ssize_t size;
  int i;

  memset(&rst, 0, sizeof(rst));
  memset(&pst, 0, sizeof(pst));

  if (!ctx->mq_open)
    {
      return;
    }

  for (i = 0; i < MIC_DRAIN_TRIES; i++)
    {
      if (ctx->recfd >= 0)
        {
          ioctl(ctx->recfd, AUDIOIOC_GETSTATUS, (unsigned long)&rst);
        }

      if (ctx->playfd >= 0)
        {
          ioctl(ctx->playfd, AUDIOIOC_GETSTATUS, (unsigned long)&pst);
        }

      if (rst.head == rst.tail && pst.head == pst.tail)
        {
          break;
        }

      clock_gettime(CLOCK_REALTIME, &deadline);
      deadline.tv_nsec += 50 * 1000000;
      if (deadline.tv_nsec >= 1000000000)
        {
          deadline.tv_sec  += 1;
          deadline.tv_nsec -= 1000000000;
        }

      /* A timeout here is not an error -- it just means no buffer came back
       * during this slice, so re-read the counters and keep waiting.
       */

      size = mq_timedreceive(ctx->mq, (char *)&msg, sizeof(msg), &prio,
                             &deadline);
      (void)size;
    }

  printf("mic: drain rec %lu/%lu play %lu/%lu after %d\n",
         (unsigned long)rst.tail, (unsigned long)rst.head,
         (unsigned long)pst.tail, (unsigned long)pst.head, i);
}

static void mic_cleanup(struct mic_ctx_s *ctx)
{
  struct audio_buf_desc_s desc;
  int i;

  if (ctx->rec_started)
    {
      ioctl(ctx->recfd, AUDIOIOC_STOP, 0);
    }

  if (ctx->play_started)
    {
      ioctl(ctx->playfd, AUDIOIOC_STOP, 0);
    }

  /* Must run after STOP and before FREEBUFFER. */

  mic_drain(ctx);

