32	   * (board_ov5640_init). Nothing to do here.
33	   */
34	  printf("velapaw/cam: OV5640 backend (board LCD_CAM capture)\n");
35	  return 0;
36	}
37	
38	int velapaw_camera_get_frame(struct velapaw_frame *frame)
39	{
40	  uint8_t *buf = NULL;
41	  int w = 0, h = 0;
42	
43	  if (frame == NULL)
44	    {
45	      return -1;
46	    }
47	
48	  if (board_ov5640_capture(&buf, &w, &h) != 0 || buf == NULL || w <= 0 || h <= 0)
49	    {
50	      /* capture failed: keep the previous frame (or black on first call) */
51	    }
52	  else
53	    {
54	      for (int y = 0; y < VELAPAW_FRAME_H; y++)
55	        {
56	          int sy = y * h / VELAPAW_FRAME_H;
57	          for (int x = 0; x < VELAPAW_FRAME_W; x++)
58	            {
59	              int sx = x * w / VELAPAW_FRAME_W;
60	              int mx = (w - 1) - sx;                 /* selfie mirror (rear lens) */
61	              const uint8_t *p = buf + ((size_t)sy * w + mx) * 2;
62	
63	              /* RGB565, big-endian byte order in the capture buffer */
64	              uint16_t px = (uint16_t)((p[0] << 8) | p[1]);
65	              uint8_t r = (px >> 11) & 0x1f;
66	              uint8_t g = (px >> 5)  & 0x3f;
67	              uint8_t b =  px        & 0x1f;
68	
69	              int o = (y * VELAPAW_FRAME_W + x) * 3;
70	              g_framebuf[o + 0] = (uint8_t)((r << 3) | (r >> 2));
71	              g_framebuf[o + 1] = (uint8_t)((g << 2) | (g >> 4));
72	              g_framebuf[o + 2] = (uint8_t)((b << 3) | (b >> 2));
73	            }
74	        }
75	    }
76	
77	  frame->data     = g_framebuf;
78	  frame->width    = VELAPAW_FRAME_W;
79	  frame->height   = VELAPAW_FRAME_H;
80	  frame->channels = VELAPAW_FRAME_C;
81	  return 0;
82	}
