206	 * quantises to 6 dB steps (es8311_setmicgain -> ES8311_ADC_REG16).
207	 *
208	 * This MUST be issued AFTER the AUDIO_TYPE_INPUT configure: es8311_configure
209	 * calls es8311_reset(), which hard-writes REG16 = 0x20 and would wipe any
210	 * gain set beforehand.  es8311_start touches REG17 (digital volume) but not
211	 * REG16, so a gain set here survives START.
212	 */
213	
214	static int mic_set_gain(int fd, uint32_t db)
215	{
216	  struct audio_caps_desc_s desc;
217	
218	  memset(&desc, 0, sizeof(desc));
219	  desc.caps.ac_len            = sizeof(struct audio_caps_s);
220	  desc.caps.ac_type           = AUDIO_TYPE_FEATURE;
221	  desc.caps.ac_format.hw      = AUDIO_FU_INP_GAIN;
222	  desc.caps.ac_controls.hw[0] = (uint16_t)db;
223	
224	  if (ioctl(fd, AUDIOIOC_CONFIGURE, (unsigned long)&desc) < 0)
225	    {
226	      printf("mic: set gain %lu dB failed: %d\n",
227	             (unsigned long)db, errno);
228	      return -errno;
229	    }
230	
231	  printf("mic: ADC gain %lu dB\n", (unsigned long)db);
232	  return 0;
233	}
234	
235	static void mic_dcblock(int16_t *audio, size_t nsamples);
236	
237	/* Read the DEVICE-level state out of the audio upper half.
238	 *
239	 * AUDIOIOC_GETSTATUS memcpys upper->status, and upper->status->state is the
240	 * exact field that both audio_configure() and audio_start() branch on -- and
241	 * both of them have a silent-success path:
242	 *
243	 *   audio_configure() calls the lower half ONLY when the state is OPEN(0)
244	 *   (for INPUT/OUTPUT types).  Any other state skips the body, leaves ret at
245	 *   OK and returns 0 -- es8311_configure() never runs, so audio_mode keeps
246	 *   whatever es8311_initialize() left it at, which is ES_MODULE_DAC.
247	 *
248	 *   audio_start() calls lower->ops->start ONLY when the state is PREPARED(1)
249	 *   or XRUN(3).  It returns -EPERM for OPEN(0), but for anything else it
250	 *   falls through to "return OK" WITHOUT starting the codec.
251	 *
252	 * Either way the ioctl returns 0 and nothing happens, which is
253	 * indistinguishable from success at the application level.  That is why this
254	 * is measured rather than assumed.
255	 *
256	 * head is the decisive counter: audio_enqueuebuffer() increments
257	 * upper->status->head only AFTER lower->ops->enqueuebuffer() has returned OK,
258	 * so head == nrecbufs proves every record buffer really did land in the
259	 * es8311 pending queue.
260	 *
261	 * States: 0 OPEN, 1 PREPARED, 2 PAUSED, 3 XRUN, 4 DRAINING, 5 RUNNING.
262	 */
263	
264	static void mic_status(int fd, const char *tag)
265	{
266	  struct audio_status_s st;
267	
268	  memset(&st, 0, sizeof(st));
269	  if (ioctl(fd, AUDIOIOC_GETSTATUS, (unsigned long)&st) < 0)
270	    {
271	      printf("mic: [%-10s] GETSTATUS failed: %d\n", tag, errno);
272	      return;
273	    }
274	
275	  printf("mic: [%-10s] state=%d head=%lu tail=%lu\n",
276	         tag, st.state, (unsigned long)st.head, (unsigned long)st.tail);
277	}
278	
279	static int mic_alloc_buffer(int fd, struct ap_buffer_s **out, int numbytes)
280	{
281	  struct audio_buf_desc_s desc;
282	  int ret;
283	
284	  memset(&desc, 0, sizeof(desc));
285	  desc.numbytes  = numbytes;
286	  desc.u.pbuffer = out;
287	
288	  ret = ioctl(fd, AUDIOIOC_ALLOCBUFFER, (unsigned long)&desc);
289	  if (ret != sizeof(desc))
290	    {
291	      printf("mic: AUDIOIOC_ALLOCBUFFER failed: %d\n", ret);
292	      return -ENOMEM;
293	    }
294	
295	  return 0;
296	}
297	
298	static int mic_enqueue(int fd, struct ap_buffer_s *apb)
299	{
300	  struct audio_buf_desc_s desc;
301	
302	  memset(&desc, 0, sizeof(desc));
303	  desc.numbytes  = apb->nmaxbytes;
304	  desc.u.buffer  = apb;
305	
306	  if (ioctl(fd, AUDIOIOC_ENQUEUEBUFFER, (unsigned long)&desc) < 0)
307	    {
308	      return -errno;
309	    }
310	
311	  return 0;
312	}
313	
314	/* Wait for every enqueued buffer to come back before freeing any of them.
315	 *
316	 * A capture ends with all four record buffers still enqueued -- the receive
317	 * loop requeues each one the moment it has copied it out.  AUDIOIOC_STOP does
318	 * NOT bring those home: es8311_stop asks its worker to terminate, and the
319	 * worker only hands back buffers still sitting in es8311's own pendq.
320	 * Anything already passed down to I2S_RECEIVE stays in the esp32s3 driver's
321	 * rx.act / rx.pend queues, because es8311 issues no I2S_IOCTL at all (see
322	 * board/patches/README.md patch #11) and so never tells the I2S layer to stop.
323	 *
324	 * Freeing them at that point leaves the I2S layer holding buffer containers
325	 * that point at released ap_buffer_s memory, and the NEXT capture inherits it:
326	 * i2s_rxdma_start() bails out early while rx.act is non-empty, so RX is never
327	 * re-armed.  That is exactly what a second "velapaw kws mic" in the same boot
328	 * showed -- one buffer delivered (4092 B), then nothing.
329	 *
330	 * tail counts completions and head counts accepted enqueues, so tail == head
331	 * on both devices means nothing is in flight.  Bounded, because a wedged
332	 * driver must not hang the shell.
333	 */
334	
335	#define MIC_DRAIN_TRIES  20      /* x 50 ms = 1 s worst case */
336	
337	static void mic_drain(struct mic_ctx_s *ctx)
338	{
339	  struct audio_status_s rst;
340	  struct audio_status_s pst;
341	  struct audio_msg_s msg;
342	  struct timespec deadline;
343	  unsigned int prio;
344	  ssize_t size;
345	  int i;
346	
347	  memset(&rst, 0, sizeof(rst));
348	  memset(&pst, 0, sizeof(pst));
349	
350	  if (!ctx->mq_open)
351	    {
352	      return;
353	    }
354	
355	  for (i = 0; i < MIC_DRAIN_TRIES; i++)
356	    {
357	      if (ctx->recfd >= 0)
358	        {
359	          ioctl(ctx->recfd, AUDIOIOC_GETSTATUS, (unsigned long)&rst);
360	        }
361	
362	      if (ctx->playfd >= 0)
363	        {
364	          ioctl(ctx->playfd, AUDIOIOC_GETSTATUS, (unsigned long)&pst);
365	        }
366	
367	      if (rst.head == rst.tail && pst.head == pst.tail)
368	        {
369	          break;
370	        }
371	
372	      clock_gettime(CLOCK_REALTIME, &deadline);
373	      deadline.tv_nsec += 50 * 1000000;
374	      if (deadline.tv_nsec >= 1000000000)
375	        {
376	          deadline.tv_sec  += 1;
377	          deadline.tv_nsec -= 1000000000;
378	        }
379	
380	      /* A timeout here is not an error -- it just means no buffer came back
381	       * during this slice, so re-read the counters and keep waiting.
382	       */
383	
384	      size = mq_timedreceive(ctx->mq, (char *)&msg, sizeof(msg), &prio,
385	                             &deadline);
386	      (void)size;
387	    }
388	
389	  printf("mic: drain rec %lu/%lu play %lu/%lu after %d\n",
390	         (unsigned long)rst.tail, (unsigned long)rst.head,
391	         (unsigned long)pst.tail, (unsigned long)pst.head, i);
392	}
393	
394	static void mic_cleanup(struct mic_ctx_s *ctx)
395	{
396	  struct audio_buf_desc_s desc;
397	  int i;
398	
399	  if (ctx->rec_started)
400	    {
401	      ioctl(ctx->recfd, AUDIOIOC_STOP, 0);
402	    }
403	
404	  if (ctx->play_started)
405	    {
406	      ioctl(ctx->playfd, AUDIOIOC_STOP, 0);
407	    }
408	
409	  /* Must run after STOP and before FREEBUFFER. */
410	
411	  mic_drain(ctx);
412	
413	  if (ctx->mq_open)
414	    {
415	      if (ctx->recfd >= 0)
416	        {
417	          ioctl(ctx->recfd, AUDIOIOC_UNREGISTERMQ, (unsigned long)ctx->mq);
418	        }
419	
420	      if (ctx->playfd >= 0)
421	        {
422	          ioctl(ctx->playfd, AUDIOIOC_UNREGISTERMQ, (unsigned long)ctx->mq);
423	        }
424	    }
425	
426	  for (i = 0; i < ctx->nrecbufs; i++)
427	    {
428	      if (ctx->recbufs[i] != NULL)
429	        {
430	          memset(&desc, 0, sizeof(desc));
431	          desc.u.buffer = ctx->recbufs[i];
432	          ioctl(ctx->recfd, AUDIOIOC_FREEBUFFER, (unsigned long)&desc);
433	          ctx->recbufs[i] = NULL;
434	        }
435	    }
436	
437	  if (ctx->playbuf != NULL)
438	    {
439	      memset(&desc, 0, sizeof(desc));
440	      desc.u.buffer = ctx->playbuf;
441	      ioctl(ctx->playfd, AUDIOIOC_FREEBUFFER, (unsigned long)&desc);
442	      ctx->playbuf = NULL;
443	    }
444	
445	  if (ctx->rec_reserved)
446	    {
447	      ioctl(ctx->recfd, AUDIOIOC_RELEASE, 0);
448	    }
449	
450	  if (ctx->play_reserved)
451	    {
452	      ioctl(ctx->playfd, AUDIOIOC_RELEASE, 0);
453	    }
454	
455	  if (ctx->mq_open)
456	    {
457	      mq_close(ctx->mq);
458	      mq_unlink(ctx->mqname);
459	    }
460	
461	  if (ctx->recfd >= 0)
462	    {
463	      close(ctx->recfd);
464	    }
465	
466	  if (ctx->playfd >= 0)
467	    {
468	      close(ctx->playfd);
469	    }
470	}
