472	/****************************************************************************
473	 * Public Functions
474	 ****************************************************************************/
475	
476	int velapaw_mic_capture(int16_t *dest, size_t nsamples,
477	                        unsigned int timeout_ms)
478	{
479	  struct mic_ctx_s ctx;
480	  struct ap_buffer_info_s bufinfo;
481	  struct ap_buffer_info_s playbufinfo;
482	  struct audio_msg_s msg;
483	  struct mq_attr attr;
484	  char inpath[MIC_PATH_MAX];
485	  char outpath[MIC_PATH_MAX];
486	  struct timespec deadline;
487	  size_t want;
488	  size_t got = 0;
489	  uint8_t *out = (uint8_t *)dest;
490	  unsigned int prio;
491	  ssize_t size;
492	  int ret;
493	  int i;
494	
495	  if (dest == NULL || nsamples == 0)
496	    {
497	      return -EINVAL;
498	    }
499	
500	  want = nsamples * sizeof(int16_t);
501	
502	  memset(&ctx, 0, sizeof(ctx));
503	  ctx.recfd  = -1;
504	  ctx.playfd = -1;
505	
506	  ret = mic_find_devices(inpath, outpath, sizeof(inpath));
507	  if (ret < 0)
508	    {
509	      return ret;
510	    }
511	
512	  ctx.recfd = open(inpath, O_RDWR | O_CLOEXEC);
513	  if (ctx.recfd < 0)
514	    {
515	      printf("mic: open %s failed: %d\n", inpath, errno);
516	      ret = -errno;
517	      goto out;
518	    }
519	
520	  ctx.playfd = open(outpath, O_RDWR | O_CLOEXEC);
521	  if (ctx.playfd < 0)
522	    {
523	      printf("mic: open %s failed: %d\n", outpath, errno);
524	      ret = -errno;
525	      goto out;
526	    }
527	
528	  if (ioctl(ctx.recfd, AUDIOIOC_RESERVE, 0) < 0)
529	    {
530	      printf("mic: reserve record failed: %d\n", errno);
531	      ret = -errno;
532	      goto out;
533	    }
534	
535	  ctx.rec_reserved = true;
536	
537	  if (ioctl(ctx.playfd, AUDIOIOC_RESERVE, 0) < 0)
538	    {
539	      printf("mic: reserve playback failed: %d\n", errno);
540	      ret = -errno;
541	      goto out;
542	    }
543	
544	  ctx.play_reserved = true;
545	
546	  ret = mic_configure(ctx.recfd, AUDIO_TYPE_INPUT);
547	  if (ret < 0)
548	    {
549	      goto out;
550	    }
551	
552	  /* Must read state=1 (PREPARED).  If it reads 0 (OPEN), the CONFIGURE was a
553	   * silent no-op and the record node is still in ES_MODULE_DAC -- which sends
554	   * its buffers to I2S_SEND and starves RX exactly as observed.
555	   */
556	
557	  mic_status(ctx.recfd, "rec cfg");
558	
559	  /* Configured to match the record side.  TX is only ever fed silence here,
560	   * but it generates the clock RX runs on, so its frame geometry has to be
561	   * the same or RX samples at the wrong rate.
562	   */
563	
564	  ret = mic_configure(ctx.playfd, AUDIO_TYPE_OUTPUT);
565	  if (ret < 0)
566	    {
567	      goto out;
568	    }
569	
570	  mic_status(ctx.playfd, "play cfg");
571	
572	  /* Gain goes here, after BOTH configures, deliberately.
573	   *
574	   * pcm0 and pcm_in0 are two independent es8311 priv structs driving ONE
575	   * physical codec, and es8311_configure calls es8311_reset() on whichever
576	   * priv it was handed.  So configuring playback re-resets the chip and
577	   * would wipe a gain applied straight after the record configure.
578	   *
579	   * Build 41 captured peak 32409 with 12 railed samples on a 32767 scale --
580	   * the ADC is clipping at the reset default (REG16 = 0x20), so the loudest
581	   * part of every word is flat-topped and the model cannot discriminate it.
582	   */
583	
584	  mic_set_gain(ctx.recfd, MIC_GAIN_DB);
585	
586	  /* GETBUFFERINFO is NOT just a query -- it is what arms allocation.
587	   *
588	   * audio.c's AUDIOIOC_GETBUFFERINFO handler copies the driver's reply into
589	   * upper->nbuffers as a side effect, and audio_allocbuffer() opens with
590	   * "if (upper->periods >= upper->nbuffers) return 0;".  Skip the query on a
591	   * device and its nbuffers stays 0, so the very first ALLOCBUFFER on it
592	   * returns 0 -- not a negative errno, literally zero, which reads like
593	   * success to anything checking for < 0.
594	   *
595	   * So it has to be issued on BOTH devices: the counter lives in the
596	   * per-device upper half, and answering for the record node does nothing for
597	   * the playback node.  nxlooper does the same, once per device.
598	   *
599	   * The reply is reported rather than assumed, because 4 x 8192 happens to be
600	   * both the es8311 driver's answer and the CONFIG_AUDIO_* fallback below --
601	   * identical numbers, opposite meanings.
602	   */
603	
604	  ret = ioctl(ctx.recfd, AUDIOIOC_GETBUFFERINFO, (unsigned long)&bufinfo);
605	  printf("mic: record GETBUFFERINFO ret=%d\n", ret);
606	  if (ret != OK)
607	    {
608	      bufinfo.buffer_size = CONFIG_AUDIO_BUFFER_NUMBYTES;
609	      bufinfo.nbuffers    = CONFIG_AUDIO_NUM_BUFFERS;
610	    }
611	
612	  ret = ioctl(ctx.playfd, AUDIOIOC_GETBUFFERINFO,
613	              (unsigned long)&playbufinfo);
614	  printf("mic: playback GETBUFFERINFO ret=%d\n", ret);
615	  if (ret != OK)
616	    {
617	      playbufinfo.buffer_size = CONFIG_AUDIO_BUFFER_NUMBYTES;
618	      playbufinfo.nbuffers    = CONFIG_AUDIO_NUM_BUFFERS;
619	    }
620	
621	  if (bufinfo.nbuffers > MIC_MAX_BUFS)
622	    {
623	      bufinfo.nbuffers = MIC_MAX_BUFS;
624	    }
625	
626	  printf("mic: %d buffers x %d B, want %u samples\n",
627	         (int)bufinfo.nbuffers, (int)bufinfo.buffer_size, (unsigned)nsamples);
628	
629	  for (i = 0; i < bufinfo.nbuffers; i++)
630	    {
631	      ret = mic_alloc_buffer(ctx.recfd, &ctx.recbufs[i],
632	                             bufinfo.buffer_size);
633	      if (ret < 0)
634	        {
635	          goto out;
636	        }
637	
638	      ctx.nrecbufs = i + 1;
639	    }
640	
641	  ret = mic_alloc_buffer(ctx.playfd, &ctx.playbuf, playbufinfo.buffer_size);
642	  if (ret < 0)
643	    {
644	      goto out;
645	    }
646	
647	  snprintf(ctx.mqname, sizeof(ctx.mqname), "/vpmic%d", (int)getpid());
648	
649	  attr.mq_maxmsg  = bufinfo.nbuffers + 8;
650	  attr.mq_msgsize = sizeof(struct audio_msg_s);
651	  attr.mq_curmsgs = 0;
652	  attr.mq_flags   = 0;
653	
654	  ctx.mq = mq_open(ctx.mqname, O_RDWR | O_CREAT, 0644, &attr);
655	  if (ctx.mq == (mqd_t)-1)
656	    {
657	      printf("mic: mq_open failed: %d\n", errno);
658	      ret = -errno;
659	      goto out;
660	    }
661	
662	  ctx.mq_open = true;
663	
664	  if (ioctl(ctx.recfd, AUDIOIOC_REGISTERMQ, (unsigned long)ctx.mq) < 0 ||
665	      ioctl(ctx.playfd, AUDIOIOC_REGISTERMQ, (unsigned long)ctx.mq) < 0)
666	    {
667	      printf("mic: REGISTERMQ failed: %d\n", errno);
668	      ret = -errno;
669	      goto out;
670	    }
671	
672	  for (i = 0; i < ctx.nrecbufs; i++)
673	    {
674	      ret = mic_enqueue(ctx.recfd, ctx.recbufs[i]);
675	      if (ret < 0)
676	        {
677	          printf("mic: enqueue record buffer %d failed: %d\n", i, ret);
678	          goto out;
679	        }
680	    }
681	
682	  /* head must equal ctx.nrecbufs here.  That is what proves the buffers got
683	   * past audio_enqueuebuffer() into es8311's pendq, where the worker thread
684	   * spawned by AUDIOIOC_START is supposed to find them.
685	   */
686	
687	  mic_status(ctx.recfd, "rec enq");
688	
689	  /* Prime TX with silence and start it FIRST.  Without this RX never sees a
690	   * bit clock and the dequeue loop below blocks until the timeout with zero
691	   * buffers returned.  See mic.h.
692	   */
693	
694	  memset(ctx.playbuf->samp, 0, ctx.playbuf->nmaxbytes);
695	  ctx.playbuf->nbytes  = ctx.playbuf->nmaxbytes;
696	  ctx.playbuf->curbyte = 0;
697	
698	  ret = mic_enqueue(ctx.playfd, ctx.playbuf);
699	  if (ret < 0)
700	    {
701	      printf("mic: priming TX failed: %d\n", ret);
702	      goto out;
703	    }
704	
705	  mic_status(ctx.playfd, "play enq");
706	
707	  if (ioctl(ctx.playfd, AUDIOIOC_START, 0) < 0)
708	    {
709	      printf("mic: start playback failed: %d\n", errno);
710	      ret = -errno;
711	      goto out;
712	    }
713	
714	  ctx.play_started = true;
715	
716	  mic_status(ctx.playfd, "play start");
717	
718	  if (ioctl(ctx.recfd, AUDIOIOC_START, 0) < 0)
719	    {
720	      printf("mic: start record failed: %d\n", errno);
721	      ret = -errno;
722	      goto out;
723	    }
724	
725	  ctx.rec_started = true;
726	
727	  /* Must read state=5 (RUNNING).  A state that is neither PREPARED(1) nor
728	   * XRUN(3) here means audio_start() took its silent fall-through and
729	   * es8311_start() was never called -- no worker thread, so nothing ever
730	   * drains pendq into I2S_RECEIVE, which is what "act=0 pend=0" reports.
731	   */
732	
733	  mic_status(ctx.recfd, "rec start");
734	
735	  clock_gettime(CLOCK_REALTIME, &deadline);
736	  deadline.tv_sec  += timeout_ms / 1000;
737	  deadline.tv_nsec += (long)(timeout_ms % 1000) * 1000000;
738	  if (deadline.tv_nsec >= 1000000000)
739	    {
740	      deadline.tv_sec  += 1;
741	      deadline.tv_nsec -= 1000000000;
742	    }
743	
744	  while (got < want)
745	    {
746	      size = mq_timedreceive(ctx.mq, (char *)&msg, sizeof(msg), &prio,
747	                             &deadline);
748	      if (size != sizeof(msg))
749	        {
750	          printf("mic: timed out with %u/%u bytes\n",
751	                 (unsigned)got, (unsigned)want);
752	
753	          /* tail counts completions.  Comparing these against the readings
754	           * taken before the wait separates "RX never started" from "RX ran
755	           * and returned empty buffers".
756	           */
757	
758	          mic_status(ctx.recfd, "rec t/out");
759	          mic_status(ctx.playfd, "play t/out");
760	
761	          ret = -ETIMEDOUT;
762	          goto out;
763	        }
764	
765	      if (msg.msg_id == AUDIO_MSG_DEQUEUE)
766	        {
767	          struct ap_buffer_s *apb = (struct ap_buffer_s *)msg.u.ptr;
768	          size_t copy;
769	
770	          if (apb == NULL)
771	            {
772	              continue;
773	            }
774	
775	          /* A playback buffer coming back is the primed silence completing.
776	           * Do not treat it as captured audio -- and do not requeue it, so
777	           * TX stays quiet while RX keeps the clock it already has.
778	           */
779	
780	          if (apb == ctx.playbuf)
781	            {
782	              continue;
783	            }
784	
785	          copy = apb->nbytes;
786	          if (copy > want - got)
787	            {
788	              copy = want - got;
789	            }
790	
791	          memcpy(out + got, apb->samp, copy);
792	          got += copy;
793	
794	          if (got < want)
795	            {
796	              apb->nbytes  = 0;
797	              apb->curbyte = 0;
798	              if (mic_enqueue(ctx.recfd, apb) < 0)
799	                {
800	                  break;
801	                }
802	            }
803	        }
804	      else if (msg.msg_id == AUDIO_MSG_STOP ||
805	               msg.msg_id == AUDIO_MSG_COMPLETE)
806	        {
807	          break;
808	        }
809	    }
810	
811	  ret = (int)(got / sizeof(int16_t));
812	  mic_dcblock(dest, (size_t)ret);
813	
814	out:
815	  mic_cleanup(&ctx);
816	  return ret;
817	}
818	
819	/* Subtract the mean.  Build 41 measured dc = -8585 on a 32767 scale -- a
820	 * quarter of full range spent on a constant offset, which both eats headroom
821	 * on one side (asymmetric clipping) and shows up as a large DC bin the
822	 * feature front end never expects.  Cheap to fix here and it keeps the driver
823	 * untouched.
824	 */
825	
826	static void mic_dcblock(int16_t *audio, size_t nsamples)
827	{
828	  long sum = 0;
829	  long dc;
830	  size_t i;
831	
832	  if (nsamples == 0)
833	    {
834	      return;
835	    }
836	
837	  for (i = 0; i < nsamples; i++)
838	    {
839	      sum += audio[i];
840	    }
841	
842	  dc = sum / (long)nsamples;
843	  if (dc == 0)
844	    {
845	      return;
846	    }
847	
