**`mic_isqrt` + rewritten `velapaw_mic_stats` (build 45) — the decisive diagnostic:**
```c
static unsigned long mic_isqrt(unsigned long long v)
{
  unsigned long long rem = 0;
  unsigned long long root = 0;
  int i;

  for (i = 0; i < 32; i++)
    {
      root <<= 1;
      rem = (rem << 2) | (v >> 62);
      v <<= 2;

      if (root < rem)
        {
          rem -= root | 1;
          root += 2;
        }
    }

  return (unsigned long)(root >> 1);
}

void velapaw_mic_stats(const int16_t *audio, size_t nsamples)
{
  unsigned long long sq = 0;
  long sum = 0;
  int peak = 0;
  size_t peakidx = 0;
  int rail = 0;
  int seg[8];
  size_t seglen;
  size_t i;
  int s;

  if (nsamples == 0)
    {
      printf("mic: no samples\n");
      return;
    }

  memset(seg, 0, sizeof(seg));
  seglen = (nsamples + 7) / 8;

  for (i = 0; i < nsamples; i++)
    {
      int v = audio[i];
      int a = v < 0 ? -v : v;

      if (a > peak)
        {
          peak    = a;
          peakidx = i;
        }

      if (a >= 32700)
        {
          rail++;
        }

      s = (int)(i / seglen);
      if (s < 8 && a > seg[s])
        {
          seg[s] = a;
        }

      sq  += (unsigned long long)((long)v * v);
      sum += v;
    }

  printf("mic: %u samples, peak %d@%u, rms %lu, dc %ld, rail %d\n",
         (unsigned)nsamples, peak, (unsigned)peakidx,
         mic_isqrt(sq / nsamples), sum / (long)nsamples, rail);

  printf("mic: profile");
  for (s = 0; s < 8; s++)
    {
      printf(" %5d", seg[s]);
    }

  printf("\n");
}
```

