333	/* Read the DEVICE-level state out of the audio upper half.
334	 *
335	 * AUDIOIOC_GETSTATUS memcpys upper->status, and upper->status->state is the
336	 * exact field that both audio_configure() and audio_start() branch on -- and
337	 * both of them have a silent-success path:
338	 *
339	 *   audio_configure() calls the lower half ONLY when the state is OPEN(0)
340	 *   (for INPUT/OUTPUT types).  Any other state skips the body, leaves ret at
341	 *   OK and returns 0 -- es8311_configure() never runs, so audio_mode keeps
342	 *   whatever es8311_initialize() left it at, which is ES_MODULE_DAC.
343	 *
344	 *   audio_start() calls lower->ops->start ONLY when the state is PREPARED(1)
345	 *   or XRUN(3).  It returns -EPERM for OPEN(0), but for anything else it
346	 *   falls through to "return OK" WITHOUT starting the codec.
347	 *
348	 * Either way the ioctl returns 0 and nothing happens, which is
349	 * indistinguishable from success at the application level.  That is why this
350	 * is measured rather than assumed.
351	 *
352	 * head is the decisive counter: audio_enqueuebuffer() increments
353	 * upper->status->head only AFTER lower->ops->enqueuebuffer() has returned OK,
354	 * so head == nrecbufs proves every record buffer really did land in the
355	 * es8311 pending queue.
356	 *
357	 * With a persistent session these counters are cumulative for the life of the
358	 * session rather than for one capture, so read them as "in flight = head -
359	 * tail", not as absolute numbers.
360	 *
361	 * States: 0 OPEN, 1 PREPARED, 2 PAUSED, 3 XRUN, 4 DRAINING, 5 RUNNING.
362	 */
363	
364	static void mic_status(int fd, const char *tag)
365	{
366	  struct audio_status_s st;
367	
368	  memset(&st, 0, sizeof(st));
369	  if (ioctl(fd, AUDIOIOC_GETSTATUS, (unsigned long)&st) < 0)
370	    {
371	      printf("mic: [%-10s] GETSTATUS failed: %d\n", tag, errno);
372	      return;
373	    }
374	
375	  printf("mic: [%-10s] state=%d head=%lu tail=%lu\n",
376	         tag, st.state, (unsigned long)st.head, (unsigned long)st.tail);
377	}
